import{_ as t,o as i,c as a,a2 as r}from"./chunks/framework.e4u2V5E7.js";const p=JSON.parse('{"title":"Security Review Playbook","description":"Engineering playbook for security review workflow","frontmatter":{"title":"Security Review Playbook","description":"Engineering playbook for security review workflow"},"headers":[],"relativePath":"playbooks/security-review.md","filePath":"playbooks/security-review.md","lastUpdated":1784485118000}'),s={name:"playbooks/security-review.md"};function o(l,e,n,d,c,u){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="security-review-playbook" tabindex="-1">Security Review Playbook <a class="header-anchor" href="#security-review-playbook" aria-label="Permalink to &quot;Security Review Playbook&quot;">​</a></h1><h1 id="playbook-security-review" tabindex="-1">Playbook: Security Review <a class="header-anchor" href="#playbook-security-review" aria-label="Permalink to &quot;Playbook: Security Review&quot;">​</a></h1><p><strong>Goal:</strong> Identify and remediate security vulnerabilities across the full stack.</p><p><strong>Trigger:</strong> Security audit request, new auth implementation, pre-deployment check, vulnerability report.</p><p><strong>Inputs:</strong></p><ul><li>Files or area to review</li><li>Authentication mechanism used</li><li>Data sensitivity level</li><li>Compliance requirements (if any)</li></ul><p><strong>Outputs:</strong></p><ul><li>Security assessment report</li><li>Vulnerabilities identified with severity</li><li>Remediations applied</li><li>Security guidelines updated</li></ul><p>----|------| | <code>security</code> | Primary auditor — vulnerability assessment, OWASP | | <code>backend</code> | Server-side security — auth, input validation | | <code>database</code> | Data security — RLS, encryption, access control | | <code>reviewer</code> | Verify security fixes | | <code>architect</code> | Security architecture review |</p><h2 id="required-skills" tabindex="-1">Required Skills <a class="header-anchor" href="#required-skills" aria-label="Permalink to &quot;Required Skills&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>When to Load</th></tr></thead><tbody><tr><td><code>security-audit</code></td><td>Always — full security assessment</td></tr><tr><td><code>authentication-patterns</code></td><td>Auth implementation review</td></tr><tr><td><code>environment-secrets</code></td><td>Secrets management review</td></tr><tr><td><code>owasp-top-10</code></td><td>OWASP vulnerability checklist</td></tr><tr><td><code>api-security</code></td><td>API-specific security</td></tr><tr><td><code>database-security</code></td><td>Database access control</td></tr></tbody></table><h2 id="required-commands" tabindex="-1">Required Commands <a class="header-anchor" href="#required-commands" aria-label="Permalink to &quot;Required Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>When to Use</th></tr></thead><tbody><tr><td><code>/security-scan</code></td><td>Always — full security scan</td></tr><tr><td><code>/review</code></td><td>After remediation — verify fixes</td></tr></tbody></table><hr><h2 id="process" tabindex="-1">Process <a class="header-anchor" href="#process" aria-label="Permalink to &quot;Process&quot;">​</a></h2><h3 id="step-1-scope-5-min" tabindex="-1">Step 1: Scope (5 min) <a class="header-anchor" href="#step-1-scope-5-min" aria-label="Permalink to &quot;Step 1: Scope (5 min)&quot;">​</a></h3><ol><li><strong>Define review area</strong> — Which files, routes, or systems?</li><li><strong>Identify attack surface</strong> — What&#39;s exposed to users?</li><li><strong>Classify data</strong> — What sensitivity level?</li><li><strong>Check known issues</strong> — Previous findings, CVEs</li></ol><h3 id="step-2-scan-20-min" tabindex="-1">Step 2: Scan (20 min) <a class="header-anchor" href="#step-2-scan-20-min" aria-label="Permalink to &quot;Step 2: Scan (20 min)&quot;">​</a></h3><p><strong>OWASP Top 10 checklist:</strong></p><ol><li><p><strong>Injection</strong> — SQL, NoSQL, OS command injection</p><ul><li>Check: User input in queries, commands, template literals</li><li>Fix: Parameterized queries, input validation</li></ul></li><li><p><strong>Broken Authentication</strong> — Weak auth mechanisms</p><ul><li>Check: Password hashing, session management, MFA</li><li>Fix: bcrypt/argon2, secure sessions, MFA</li></ul></li><li><p><strong>Sensitive Data Exposure</strong> — Unprotected data</p><ul><li>Check: HTTPS, encryption at rest, logging sensitive data</li><li>Fix: TLS, encryption, redact logs</li></ul></li><li><p><strong>XML External Entities</strong> — XXE injection</p><ul><li>Check: XML parsing configuration</li><li>Fix: Disable external entities</li></ul></li><li><p><strong>Broken Access Control</strong> — Missing authorization</p><ul><li>Check: Role checks, IDOR, privilege escalation</li><li>Fix: Server-side auth checks, RLS</li></ul></li><li><p><strong>Security Misconfiguration</strong> — Default configs</p><ul><li>Check: Error messages, headers, CORS</li><li>Fix: Secure defaults, custom errors</li></ul></li><li><p><strong>Cross-Site Scripting (XSS)</strong> — Unescaped output</p><ul><li>Check: User input in HTML, React dangerouslySetInnerHTML</li><li>Fix: Input validation, output encoding</li></ul></li><li><p><strong>Insecure Deserialization</strong> — Untrusted data</p><ul><li>Check: Object parsing from user input</li><li>Fix: Validate, integrity checks</li></ul></li><li><p><strong>Using Components with Known Vulnerabilities</strong> — Outdated deps</p><ul><li>Check: <code>npm audit</code>, outdated packages</li><li>Fix: Update, replace, patch</li></ul></li><li><p><strong>Insufficient Logging</strong> — Missing audit trail</p><ul><li>Check: Auth events, errors, access attempts</li><li>Fix: Comprehensive logging</li></ul></li></ol><h3 id="step-3-test-10-min" tabindex="-1">Step 3: Test (10 min) <a class="header-anchor" href="#step-3-test-10-min" aria-label="Permalink to &quot;Step 3: Test (10 min)&quot;">​</a></h3><ol><li><strong>Manual testing</strong> — Try to exploit found vulnerabilities</li><li><strong>Input validation</strong> — Inject malicious input</li><li><strong>Auth testing</strong> — Try privilege escalation</li><li><strong>Session testing</strong> — Cookie security, token validation</li></ol><h3 id="step-4-remediate-varies" tabindex="-1">Step 4: Remediate (varies) <a class="header-anchor" href="#step-4-remediate-varies" aria-label="Permalink to &quot;Step 4: Remediate (varies)&quot;">​</a></h3><ol><li><strong>Critical/High</strong> — Fix immediately</li><li><strong>Medium</strong> — Fix before deployment</li><li><strong>Low</strong> — Fix when convenient</li><li><strong>Document</strong> — Why each fix is needed</li></ol><h3 id="step-5-verify-10-min" tabindex="-1">Step 5: Verify (10 min) <a class="header-anchor" href="#step-5-verify-10-min" aria-label="Permalink to &quot;Step 5: Verify (10 min)&quot;">​</a></h3><ol><li><strong>Re-scan</strong> — Confirm vulnerabilities are fixed</li><li><strong>Test fixes</strong> — Verify remediation works</li><li><strong>Run <code>/security-scan</code></strong> — Automated verification</li><li><strong>Review fixes</strong> — No new issues introduced</li></ol><hr><h2 id="validation-steps" tabindex="-1">Validation Steps <a class="header-anchor" href="#validation-steps" aria-label="Permalink to &quot;Validation Steps&quot;">​</a></h2><ul><li>[ ] All OWASP Top 10 categories checked</li><li>[ ] Critical and high vulnerabilities fixed</li><li>[ ] No hardcoded secrets</li><li>[ ] Input validation at all boundaries</li><li>[ ] Auth checks on all protected routes</li><li>[ ] HTTPS enforced</li><li>[ ] Sensitive data encrypted</li><li>[ ] Errors don&#39;t leak information</li><li>[ ] Logging covers security events</li></ul><h2 id="success-criteria" tabindex="-1">Success Criteria <a class="header-anchor" href="#success-criteria" aria-label="Permalink to &quot;Success Criteria&quot;">​</a></h2><ul><li>No critical or high vulnerabilities remaining</li><li>All findings documented with severity</li><li>Remediations verified</li><li>Security guidelines updated</li></ul><h2 id="common-pitfalls" tabindex="-1">Common Pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common Pitfalls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pitfall</th><th>Why It&#39;s Wrong</th><th>Correct Approach</th></tr></thead><tbody><tr><td>Client-side only auth</td><td>Trivially bypassed</td><td>Always validate server-side</td></tr><tr><td>Hardcoded secrets</td><td>Exposed in source control</td><td>Use environment variables</td></tr><tr><td>Generic error messages</td><td>Hides security issues</td><td>Log detailed, show generic</td></tr><tr><td>Trusting user input</td><td>Injection attacks</td><td>Validate and sanitize everything</td></tr><tr><td>Missing rate limiting</td><td>Brute force attacks</td><td>Add rate limiting to auth/APIs</td></tr><tr><td>Logging sensitive data</td><td>Data exposure in logs</td><td>Redact passwords, tokens, PII</td></tr><tr><td>Skipping <code>npm audit</code></td><td>Known vulnerabilities</td><td>Run regularly, fix promptly</td></tr></tbody></table><h2 id="related-commands" tabindex="-1">Related Commands <a class="header-anchor" href="#related-commands" aria-label="Permalink to &quot;Related Commands&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/commands/">Commands Registry</a> for commands used in this playbook.</p><h2 id="related-agents" tabindex="-1">Related Agents <a class="header-anchor" href="#related-agents" aria-label="Permalink to &quot;Related Agents&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/agents/">Agents Registry</a> for agents involved in this playbook.</p>',37)])])}const g=t(s,[["render",o]]);export{p as __pageData,g as default};
